# Generated by manage.py generate_test_cases.
from functools import partial
from typing import Any

from django.core.exceptions import ValidationError

from bloomerp.models.document_signing.signature_event import SignatureEvent
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)

from .support import SigningFixturesMixin


class TestSignatureEventModel(SigningFixturesMixin, BloomerpModelTestCase):
    """Cover append-only evidence and recipient ownership boundaries."""

    model = SignatureEvent

    def event_args(self, **overrides: Any) -> dict[str, Any]:
        """Build a request event with optional recipient evidence."""
        return {
            "request": self.request,
            "event_type": SignatureEvent.EventType.CREATED,
            "payload": {"document_sha256": self.digest},
            **overrides,
        }

    def foreign_recipient_args(self) -> dict[str, Any]:
        """Attach identity evidence belonging to another signing request."""
        return self.event_args(recipient=self.other_request_recipient())

    def get_test_scenarios(self) -> list[ModelScenario[SignatureEvent]]:
        """Retain valid observations and reject edits, removal, or crossed identities."""
        return [
            ModelScenario(
                name="Retain request-wide evidence", create_args=self.event_args
            ),
            ModelScenario(
                name="Retain signer-specific evidence",
                create_args=partial(self.event_args, recipient=self.recipient),
            ),
            ModelScenario(
                name="Reject a recipient from another request",
                create_args=self.foreign_recipient_args,
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Reject edits to retained evidence",
                create_args=self.event_args,
                update_args={"event_type": SignatureEvent.EventType.SIGNED},
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Reject deletion of retained evidence",
                create_args=self.event_args,
                expected_exceptions=[ExpectedModelException("delete", ValidationError)],
            ),
            ModelScenario(
                name="Require object-shaped evidence payloads",
                create_args=partial(self.event_args, payload=[]),
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
        ]

    def test_queryset_delete_preserves_evidence(self) -> None:
        """Retain audit records even when callers delete through a queryset."""
        event = SignatureEvent.objects.create(**self.event_args())
        with self.assertRaises(ValidationError):
            SignatureEvent.objects.filter(pk=event.pk).delete()
        self.assertTrue(SignatureEvent.objects.filter(pk=event.pk).exists())
